function IdolLive3D_FreeCameraTrackNodeParams:__init( params_ )

    if isNotNull(params_.vcam) then 
        printError("此分支 未能完全支持, 请联系 苍蓝星")

        local vcamTF = params_.vcam.transform
        assert( vcamTF )
        local lens = params_.vcam.m_Lens
        
        self.fov = lens.FieldOfView
        self.xzDistance = Vector3.ProjectOnPlane(vcamTF.position - Vector3.zero, Vector3.up).magnitude -- todo: 此处的 Vector3.zero 可能是个配置参数...
        self.cameraH = vcamTF.position.y

        local dirHorizon = Vector3.ProjectOnPlane(vcamTF.forward, Vector3.up).normalized
        self.pitchDegree = Mathf.Acos( Vector3.Dot( dirHorizon, vcamTF.forward ) ) * ( vcamTF.forward.y >= 0.0 and -1.0 or 1.0 ) * Mathf.Rad2Deg -- 暂用 degree 是为了更好地 debug...
    else 
        assert( params_.fov )
        assert( params_.xzDistance )
        assert( params_.cameraH )
        assert( params_.pitchDegree )

        self.fov = params_.fov 
        self.xzDistance = params_.xzDistance 
        self.cameraH = params_.cameraH 
        self.pitchDegree = params_.pitchDegree 
    end


    if isNotNull(params_.vcamParams) then 
        local vcamParams = params_.vcamParams

        assert( isNotNull(vcamParams.fovRange) and isNotNull(vcamParams.moveRange) and isNotNull(vcamParams.range_t) )

        self.range_t = vcamParams.range_t

        self.minFov = Mathf.Clamp( self.fov - vcamParams.fovRange * self.range_t,     5, 70 )
        self.maxFov = Mathf.Clamp( self.fov + vcamParams.fovRange * (1-self.range_t), 5, 70 )
        
        self.minDistanceOffset =  - vcamParams.moveRange * self.range_t
        self.maxDistanceOffset =    vcamParams.moveRange * (1-self.range_t)
        -- todo: 需要确保 minDistanceOffset 不越界...

    else 
        assert( params_.minFov and params_.maxFov and params_.minDistanceOffset and params_.maxDistanceOffset and params_.range_t )

        self.minFov = params_.minFov
        self.maxFov = params_.maxFov
        self.minDistanceOffset = params_.minDistanceOffset
        self.maxDistanceOffset = params_.maxDistanceOffset
        self.range_t = params_.range_t

    end 


    -- t 值需通过 SetT(), GetT() 来访问:
    self.t = 0.0
end




-- 需手动调用 Delete()
