        xzDistance = a.xzDistance+b.xzDistance, minDistanceOffset = a.minDistanceOffset+b.minDistanceOffset, maxDistanceOffset = a.maxDistanceOffset+b.maxDistanceOffset,
        cameraH = a.cameraH+b.cameraH, pitchDegree = a.pitchDegree+b.pitchDegree, range_t = a.range_t+b.range_t
    })
end


function IdolLive3D_FreeCameraTrackNodeParams.Minus( a, b )
    return IdolLive3D_FreeCameraTrackNodeParams.New({ 
        fov = a.fov-b.fov, minFov = a.minFov-b.minFov, maxFov = a.maxFov-b.maxFov, 
