function IdolLive3D_FreeCameraTrackNodeParams.Scale( a, s )
    return IdolLive3D_FreeCameraTrackNodeParams.New({ 
        fov = a.fov*s, minFov = a.minFov*s, maxFov = a.maxFov*s, 
        xzDistance = a.xzDistance*s, minDistanceOffset = a.minDistanceOffset*s, maxDistanceOffset = a.maxDistanceOffset*s,
        cameraH = a.cameraH*s, pitchDegree = a.pitchDegree*s, range_t = a.range_t*s
    })
end


